from pt import *
items = [
 T(r"**Lemma 3.** Let $A \subset \mathbb{R}^d$ be a non-empty compact set with finite diameter and let $\delta \in (0, \Delta(\mathcal{X})]$. If $\mu(A) > 0$ and the $\delta$-fattening of $A$, $A_\delta$, is $(d - 1)$-rectifiable for all $\delta \in (0, \Delta(\mathcal{X})]$, then there exists a finite universal constant $c \ge 1$:", L, 57, 104),
 T(r"$$c = \max\{M/(d\mu(\mathcal{B}_1(\cdot))^{1/d}), 1\} < \infty,$$", L, 108, 126),
 T(r"where $M > 0$ is a finite constant independent of $\delta$ and $A$, such that", L, 132, 152),
 T(r"$$\frac{\lambda(\partial A_\delta)}{\mu(A_\delta)^{(d-1)/d}} \le \frac{c\,\lambda(\partial A)}{\mu(A)^{(d-1)/d}},$$", L, 148, 180),
 T(r"where $c$ is independent of $\delta$ and $A$, and $\lambda(\partial A)$ is the Minkowski Content as defined in (2).", L, 181, 204),
 T(r"The following Lemma quantifies the relationship between $\mu(A)$ and $\mu(A_\delta)$.", L, 214, 237),
 T(r"**Lemma 4.** Consider any finite, strictly positive $\delta$ and a non-empty, compact set $A \subset \mathbb{R}^d$ such that $\mu(A) > 0$ and its $\delta$-fattening, $A_\delta$, is a $(d - 1)$-rectifiable set for all $\delta \ge 0$. Then,", L, 247, 281),
 T(r"$$\mu(A_\delta) \le \left(1 + \frac{c\,\delta\lambda(\partial A)}{\mu(A)d}\right)^{d} \mu(A), \tag{3}$$", L, 287, 320),
 T(r"where $c \ge 1$ is the universal constant from Lemma 3, and $\lambda(\partial A)$ is the Minkowski Content as defined in (2).", L, 323, 345),
 T(r"**Proof:** Define the function $g : \mathbb{R}_{\ge 0} \to \mathbb{R}_{\ge 0}$ such that $g(x) = (\mu(A_x)/\mu(A))^{1/d}$, and let $h(\delta) : \mathbb{R}_{\ge 0} \to \mathbb{R}_{\ge 0}$ be the function defining the Minkowski Content $h(\delta) = \frac{\mu(A_\delta) - \mu(A)}{\delta}$. Observe that since $A_\delta$ is a $(d - 1)$-rectifiable set we have that the limit inferior of the expression in (2) is equivalent to its limit superior [19, Theorem 3.2.39], and thus the traditional limit exists:", L, 355, 437),
 T(r"$$\begin{aligned} \lambda(\partial A) &= \liminf_{\delta \to 0} \frac{\mu(A_\delta) - \mu(A)}{\delta} = \liminf_{\delta \to 0} h(\delta) \\ &= \limsup_{\delta \to 0} h(\delta) = \lim_{\delta \to 0} h(\delta). \end{aligned}$$", L, 440, 488),
 T(r"Let $\varepsilon > 0$ and define $\lambda' = \lambda(\partial A) + \varepsilon > \lambda(\partial A)$. By definition of $\lim_{\delta \to 0} h(\delta) = \lambda(\partial A)$, there exists an open interval defined by a constant (as a function of $\varepsilon$), $\xi(\varepsilon) > 0$ such that for all $\delta' \in (0, \xi(\varepsilon))$, $|h(\delta') - \lambda(\partial A)| < \varepsilon$. This implies that $h(\delta') < \lambda(\partial A) + \varepsilon$ and thus by definition of $h(\delta')$, we have for all $\delta' \in (0, \xi(\varepsilon))$", L, 495, 565),
 T(r"$$\mu(A_{\delta'}) < \mu(A) + \delta'\,(\lambda(\partial A) + \varepsilon) = \mu(A) + \delta'\,\lambda'.$$", L, 570, 587),
 T(r"Thus, for all $\delta' \in (0, \xi(\varepsilon))$, we have", L, 592, 603),
 T(r"$$\begin{aligned} g(\delta') &= \left(\frac{\mu(A_{\delta'})}{\mu(A)}\right)^{1/d} < \left(1 + \frac{\delta'\lambda'}{\mu(A)}\right)^{1/d} \le 1 + \frac{\delta'\lambda'}{\mu(A)d} \\ &\le 1 + \frac{c\delta'\lambda'}{\mu(A)d}, \end{aligned} \tag{4}$$", L, 605, 666),
 T(r"where the second to last inequality follows by Bernoulli’s inequality and the last inequality follows by the fact that $c \ge 1$. The inequality (4) implies that if $\delta \in (0, \xi(\varepsilon))$, then the inequality trivially holds and we are done. Therefore, we next consider the case where $\delta \in [\xi(\varepsilon), \Delta(\mathcal{X})]$.", L, 668, 726),
 T(r"Differentiating $g(\delta')$ with respect to $\delta'$ yields:", R, 58, 69),
 T(r"$$\begin{aligned} \frac{\mathrm{d}\,g(\delta')}{\mathrm{d}\delta'} &= \frac{1}{\mu(A)^{1/d}} \cdot \frac{\mathrm{d}\mu(A_{\delta'})^{1/d}}{\mathrm{d}\delta'} \\ &= \frac{\lambda(\partial A_{\delta'})}{\mu(A)^{1/d}\,\mu(A_{\delta'})^{(d-1)/d}\,d}, \end{aligned}$$", R, 72, 130),
 T(r"where we used the $(d - 1)$-rectifiability of $A_{\delta'}$ to replace the limit with the Minkowski Content, since the limit is ensured to exist. Moreover, note that", R, 133, 167),
 T(r"$$\begin{aligned} \frac{\mathrm{d}}{\mathrm{d}\delta'}\left(1 + \frac{c\delta'\lambda'}{\mu(A)d}\right) &= \frac{c\lambda'}{\mu(A)d} > \frac{c\lambda(\partial A)}{\mu(A)d} \\ &\ge \frac{1}{d\mu(A)^{1/d}} \cdot \frac{\lambda(\partial A_{\delta'})}{\mu(A_{\delta'})^{(d-1)/d}} = \frac{\mathrm{d}\,g(\delta')}{\mathrm{d}\delta'}, \end{aligned}$$", R, 170, 227),
 T("where the inequality follows from Lemma 3.", R, 230, 240),
 T(r"Thus, we have that for all $\delta' \in (0, \Delta(\mathcal{X})]$, $g(\delta')$ grows not faster than does the expression on the right-hand side of the inequality in (4). This observation combined with the fact that the inequality holds for all values of $\delta' \in (0, \xi(\varepsilon))$ implies that for all $\delta' \in (0, \Delta(\mathcal{X})]$, inequality (4) holds and thus we have also have for the originally specified $\delta$ that $g(\delta) \le 1 + \frac{c\delta\lambda'}{\mu(A)d}$. Finally, taking the limit of both sides of this inequality yields", R, 245, 328),
 T(r"$$\begin{aligned} g(\delta) = \lim_{\lambda' \to \lambda(\partial A)} g(\delta) &\le \lim_{\lambda' \to \lambda(\partial A)} \left(1 + \frac{c\,\lambda(\partial A)\delta}{\mu(A)d}\right) \\ &= 1 + \frac{c\,\delta\lambda(\partial A)}{\mu(A)d}, \end{aligned}$$", R, 331, 388),
 T(r"and the lemma follows by definition of $g(\delta)$. $\blacksquare$", R, 391, 402),
 T(r"For our subsequent results, we assume that a $\delta$-packing for $\mathcal{X}$, $\mathcal{S} \subset \mathcal{X}$, is generated by GreedyPack (Alg. 1) for a predefined constant $\delta \in (0, \Delta(\mathcal{X})]$. We now employ Lemma 4 to establish the amount of overlap.", R, 408, 454),
 T(r"**Lemma 5.** For all $x \in \mathcal{S}$, it follows that", R, 466, 476),
 T(r"$$f(x) \subseteq F(\mathcal{B}_\delta(x)) \subseteq f(x)_{\delta K}, \tag{5}$$", R, 481, 498),
 T(r"where $f(x)_{\delta K}$ is the $(\delta K)$-fattening of $f(x)$, $\delta > 0$ is the constant used to construct $\mathcal{S}$, and $K$ is the Lipschitz constant from Assumption 2.", R, 503, 537),
 T(r"**Proof:** By definition of $\mathcal{B}_\delta(x)$ and by Assumption 2, it follows that for all $y \in \mathcal{B}_\delta(x)$,", R, 549, 572),
 T(r"$$d_{\mathrm{H}}(f(x), f(y)) \le K\|x - y\| \le K\delta.$$", R, 576, 593),
 T(r"We have that $x \in \mathcal{B}_\delta(x)$, $f(x) \subseteq F(\mathcal{B}_\delta(x))$, and $f(x)$ is compact. Moreover for all $f(y)$, $y \in \mathcal{B}_\delta(x)$, $f(y)$ is also compact. Thus, it follows by definition of Hausdorff distance that the $(\delta K)$-fattening of $f(x)$, $f(x)_{\delta K}$ fully contains $f(y)$, i.e., $f(y) \subseteq f(x)_{\delta K}$. Since this holds for all $y \in \mathcal{B}_\delta(x)$, we have by definition of Hausdorff distance", R, 598, 668),
 T(r"$$d_{\mathrm{H}}(f(x), \cup_{y \in \mathcal{B}_\delta(x)} f(y)) = d_{\mathrm{H}}(f(x), F(\mathcal{B}_\delta(x))) \le \delta K.$$", R, 676, 690),
 T(r"The lemma then follows by definition of Hausdorff distance in terms of $(\delta K)$-fattenings. $\blacksquare$", R, 694, 718),
]
